// usage: node scratch-probe.mjs <corpusRoot> <srcDir> <componentFileRel> <ExportName> <prop,prop>
import { writeFileSync, rmSync } from 'node:fs'
import { dirname, join, resolve, basename } from 'node:path'
import { pathToFileURL, fileURLToPath } from 'node:url'
import { createRequire, registerHooks } from 'node:module'
const here = dirname(fileURLToPath(import.meta.url))
const require = createRequire(import.meta.url)
const [root, src, rel, name, props] = process.argv.slice(2)
const rootDir = resolve(root)
process.chdir(rootDir)
const file = join(rootDir, rel)
const story = join(dirname(file), `__probe__${name}.stories.tsx`)
writeFileSync(story, `import { ${name} } from './${basename(file).replace(/\.tsx?$/, '')}'\nexport default { title: 'P/${name}', component: ${name} }\nexport const Basic = {}\n`)
try {
  const which = process.env.WHICH ?? 'ours'
  let provider
  if (which === 'theirs') {
    const ts = pathToFileURL(resolve(here, '../../../apps/oracle/node_modules/typescript/lib/typescript.js')).href
    registerHooks({ resolve: (s, c, n) => (s === 'typescript' ? { url: ts, format: 'commonjs', shortCircuit: true } : n(s, c)) })
    const react = dirname(require.resolve('@storybook/react/package.json'))
    provider = (await import(pathToFileURL(join(react, 'dist/docgen/docgen-worker.js')).href)).createDocgenProvider()
  } else {
    const { createDocgenProvider } = await import(pathToFileURL(resolve(here, '../dist/provider.js')).href)
    provider = createDocgenProvider({ srcDirs: [src], loadDependencies: true, fallback: 'never' })
  }
  const handed = Symbol()
  const importPath = `./${rel.replace(/[^/]+$/, `__probe__${name}.stories.tsx`)}`
  const entry = { type: 'story', subtype: 'story', id: `p--basic`, name: 'Basic', title: 'P', importPath, tags: [] }
  const payload = await provider(async () => handed)({ entry })
  if (payload === handed) console.log('HANDED ON')
  else {
    const a = payload.argTypes ?? {}
    console.log('nprops', Object.keys(a).length)
    for (const p of props.split(',')) console.log(p, JSON.stringify(a[p], null, 1))
  }
} finally {
  rmSync(story, { force: true })
}

