import json,collections,sys
d=json.load(open('scratch/antd-none.canonical'))
print('components',len(d['components']),'props',len(d['props']),'diag',len(d['diagnostics']), 'stats',d['stats'])
kinds=collections.Counter(p['type']['kind'] for p in d['props'].values())
print(kinds.most_common())
print('diag codes',collections.Counter(x['code'] for x in d['diagnostics']).most_common())
c=[k for k in d['components'] if k.startswith('Button')]
print(c)
def props_of(k):
    ids={}
    for s in d['components'][k]['props']: ids.update(d['propSets'][s])
    return {n:d['props'][i] for n,i in ids.items()}
b=props_of('Button')
for n in ['color','size','variant','classNames','type','iconPosition']:
    print(n,json.dumps(b[n]['type'])[:300],b[n]['required'],b[n]['defaultValue'])
print('OPAQUE_TYPE msgs',[x['message'][:140] for x in d['diagnostics'] if x['code']=='OPAQUE_TYPE'][:6])
# opaque / named-only props across components (usage prop-instances)
tot=0;cat=collections.Counter()
for k in d['components']:
    for n,p in props_of(k).items():
        tot+=1
        t=p['type']['kind']
        cat[t]+=1
print('prop instances',tot,cat.most_common(8))
# diagnostics linked to components
aff=set()
for x in d['diagnostics']:
    for a in d['nameLists'].get(x.get('affects'),[]): aff.add(a)
print('components with affecting diag',len(aff),'of',len(d['components']))
# props of opaque kind in components w/o any diag
nodiag=0;opq=0
for k in d['components']:
    for n,p in props_of(k).items():
        if p['type']['kind']=='opaque':
            opq+=1
            if k not in aff: nodiag+=1
print('opaque prop instances',opq,'in components with no affecting diag',nodiag)
nm=0;nmnodiag=0
for k in d['components']:
    for n,p in props_of(k).items():
        if p['type']['kind']=='named' and not p['type']['args']:
            nm+=1
            if k not in aff: nmnodiag+=1
print('bare named prop instances',nm,'in components w/o diag',nmnodiag)
# collapsed layers
lay=0;col=0
for k,c in d['components'].items():
    for l in c['inheritance']:
        lay+=1
        if 'members' in l: col+=1
print('layers',lay,'with members',col)
# which named?
nn=collections.Counter(p['type']['name'] for p in d['props'].values() if p['type']['kind']=='named' and not p['type']['args'])
print(nn.most_common(25))

